import { ocrFailed, validation, type StructuredError } from './errors.js';

// ---------------------------------------------------------------------------
// C6: model constraint
// ---------------------------------------------------------------------------

/**
 * gemini_ocr is HARD-PINNED to gemini-2.5-flash and must never be pointed at
 * a Pro model. Rationale (C6): thinkingBudget: 0 is required to keep OCR
 * calls fast/cheap and deterministic-ish (no chain-of-thought variance in a
 * pure transcription task) — gemini-2.5-flash supports thinkingBudget: 0,
 * but gemini-2.5-pro's minimum is 128 and refuses 0. Using Pro here would
 * silently reintroduce a nonzero thinking budget (cost + latency + a source
 * of non-determinism we don't want for OCR) contrary to the tool's design.
 */
export const OCR_MODEL = 'gemini-2.5-flash' as const;

/** thinkingBudget: 0 — Flash-only. See OCR_MODEL doc for why Pro is barred. */
export const OCR_THINKING_BUDGET = 0;

export function assertOcrModelAllowed(model: string): void {
  if (model !== OCR_MODEL) {
    throw validation(
      `gemini_ocr only supports ${OCR_MODEL} (thinkingBudget:0 requires Flash; ` +
        `gemini-2.5-pro's minimum thinking budget is 128 and would silently ` +
        `change OCR behavior). Got "${model}".`,
    ) as unknown as Error;
  }
}

// ---------------------------------------------------------------------------
// Part ordering for vision calls
// ---------------------------------------------------------------------------

export interface InlineImagePart {
  inlineData: { mimeType: string; data: string };
}
export interface TextPart {
  text: string;
}
export type ContentPart = InlineImagePart | TextPart;

/**
 * Per C6: for vision OCR calls, IMAGE parts must precede the TEXT/prompt
 * part in the `contents` array. This is the OPPOSITE convention from
 * write_section.ts and friends, which send a single text `user` string
 * (there's nothing to order — no images). Gemini's multimodal grounding is
 * more reliable when the model sees the visual evidence before being told
 * what to do with it, which matters for OCR specifically (vs. e.g. a
 * text-editing task where the instruction naturally comes first).
 */
export function buildOcrParts(images: InlineImagePart[], promptText: string): ContentPart[] {
  return [...images, { text: promptText }];
}

// ---------------------------------------------------------------------------
// Inline vs Files API payload-size decision
// ---------------------------------------------------------------------------

/**
 * Gemini's inline (base64-in-request) payload limit is documented around
 * 20MB for the total request. Base64 inflates raw bytes by ~4/3, so we
 * estimate against the RAW (pre-base64) byte size and apply the same 20MB
 * threshold as the task's stated cap, treating it as "combined inline
 * payload" (i.e. already accounting for the encoding overhead implicitly by
 * being conservative — see INLINE_SIZE_LIMIT_BYTES comment).
 */
export const INLINE_SIZE_LIMIT_BYTES = 20 * 1024 * 1024; // 20MB

export interface PayloadDecision {
  useFilesApi: boolean;
  estimatedBase64Bytes: number;
}

/**
 * Decide whether a batch of page images should be sent inline or via the
 * Files API, based on estimated total payload size.
 *
 * @param rawImageByteSizes raw (pre-base64) byte length of each page PNG in
 *   the batch.
 */
export function decideUploadPath(rawImageByteSizes: number[]): PayloadDecision {
  const totalRawBytes = rawImageByteSizes.reduce((a, b) => a + b, 0);
  // Base64 encoding inflates size by ~4/3 (33%); JSON envelope overhead is
  // comparatively negligible for image-heavy payloads, so we fold it into
  // this single multiplier rather than modeling it separately.
  const estimatedBase64Bytes = Math.ceil(totalRawBytes * (4 / 3));
  return {
    useFilesApi: estimatedBase64Bytes > INLINE_SIZE_LIMIT_BYTES,
    estimatedBase64Bytes,
  };
}

/**
 * TODO (staging pass, NOT wired): actual Files API upload.
 *
 * The real @google/genai SDK exposes `client.files.upload({file, config})`
 * returning a file handle you reference in `contents` as a `fileData` part
 * instead of `inlineData`. We do not call it here — this staging pass only
 * implements the DECISION (decideUploadPath above) for real. If a batch's
 * estimated payload exceeds INLINE_SIZE_LIMIT_BYTES, gemini_ocr.ts must call
 * this function, which currently always throws a structured error telling
 * the caller to reduce batch size / rasterization DPI as a workaround, since
 * there is no working upload path yet.
 */
export async function uploadViaFilesApi(): Promise<never> {
  throw ocrFailed(
    'This batch\'s images exceed the 20MB inline payload limit and the Files API upload ' +
      'path is not yet implemented in this build. Work around it by lowering rasterization ' +
      'DPI or requesting fewer pages per call (page_range) so the batch fits under 20MB inline.',
    { limit_bytes: INLINE_SIZE_LIMIT_BYTES },
  ) as unknown as never;
}

// ---------------------------------------------------------------------------
// media_resolution selection
// ---------------------------------------------------------------------------

export type MediaResolution = 'media_resolution_medium' | 'media_resolution_high';

/**
 * media_resolution_high costs more tokens per image but preserves more
 * detail for dense/small-font pages. We key this off response_format alone
 * (not a per-page density heuristic) for this staging pass: "detailed" is
 * exactly the mode where a caller wants layout/structure notes and
 * confidence flags, which requires the model to actually resolve fine
 * detail (footnotes, marginalia, small captions) — so tying resolution to
 * that same flag is a reasonable, simple proxy. A true per-page "dense or
 * small-font" heuristic would need either a first-pass cheap detection (out
 * of scope here) or metadata from detect_text_layer.py (e.g. font size
 * histogram) that isn't emitted yet.
 */
export function selectMediaResolution(responseFormat: 'concise' | 'detailed'): MediaResolution {
  return responseFormat === 'detailed' ? 'media_resolution_high' : 'media_resolution_medium';
}

// ---------------------------------------------------------------------------
// finishReason -> actionable StructuredError
// ---------------------------------------------------------------------------

/**
 * Map a Gemini finishReason to an actionable structured error, or null if
 * the call finished normally (STOP) and the caller should proceed to parse
 * the response. Never surfaces the raw code alone (Quality Bar #20).
 */
export function mapFinishReasonError(
  finishReason: string,
  pageNumber: number,
): StructuredError | null {
  switch (finishReason) {
    case 'STOP':
      return null;
    case 'MAX_TOKENS':
      return ocrFailed(
        `Gemini ran out of output tokens on page ${pageNumber} before finishing. ` +
          `Try response_format=concise (fewer fields per page) or a smaller page_range ` +
          `per call so each batch has more token headroom.`,
        { finish_reason: finishReason, page: pageNumber },
      );
    case 'SAFETY':
      return ocrFailed(
        `Gemini stopped early (safety filter) on page ${pageNumber}. Try response_format=concise, ` +
          `or isolate this page in its own page_range call to confirm whether it reproduces.`,
        { finish_reason: finishReason, page: pageNumber },
      );
    case 'RECITATION':
      return ocrFailed(
        `Gemini stopped early (recitation filter) on page ${pageNumber} — it flagged the ` +
          `content as matching known copyrighted text closely. Try a smaller page_range ` +
          `so this page is isolated, or reduce rasterization DPI.`,
        { finish_reason: finishReason, page: pageNumber },
      );
    default:
      return ocrFailed(
        `Gemini stopped early on page ${pageNumber} for an unexpected reason (${finishReason}). ` +
          `Try re-running with a smaller page_range.`,
        { finish_reason: finishReason, page: pageNumber },
      );
  }
}
